    drag(G, x, y) { if (!G.grab) return false; game.move(G, x, y); return true; },
    release(G) { G.grab = false; },
    demo: G => (G.div ? { from: G.div, to: { x: G.div.x + 3 * G.d, y: G.div.y }, text: 'Arrastra la divisoria', ty: G.div.y - 34 } : null),
