        p.stroke(C.line); p.strokeWeight(1); p.fill(C.card); p.rect(x0, y, x1 - x0, h, 4); p.noStroke();
        p.fill(col); const xa = X(0), xb = X(v * k); p.rect(Math.min(xa, xb), y, Math.abs(xb - xa), h, 3);
