          if (whole) { p.noStroke(); p.fill(t === 0 ? C.N : t < 0 ? C.I : C.ink); p.textStyle(p.BOLD); p.textSize(12); p.textAlign(p.CENTER, p.CENTER); p.text(negTxt(t), X(t), lineY + 19); }
