            p.noStroke(); p.fill(col); p.rect(b.x - q * 16, b.y - q * 6, b.w / 2 - 2, b.h, 9, 0, 0, 9); p.rect(b.x + b.w / 2 + 2 + q * 16, b.y + q * 6, b.w / 2 - 2, b.h, 0, 9, 9, 0);
