          p.noStroke(); p.fill(C.mute); p.textStyle(p.NORMAL); p.textSize(11); p.textAlign(p.CENTER, p.CENTER);
          p.text(locked || a.phase === 'all' ? '¡Cortes limpios! Ya puedes comprobar' : 'Corta solo las que valen lo mismo', W / 2, H - 16);
