      for (const o of b.buoys) { p.stroke(C.night ?? C.ink); p.strokeWeight(1.5); p.fill(C.coral); p.circle(o.x, o.y, BUOY * 2); p.noStroke(); p.fill(C.cream); p.rect(o.x - BUOY, o.y - 1.5, BUOY * 2, 3); }
