    const solution = params.rounds.map(r => r.orders.map(o => (r.mode === 'pick' ? `${o.say} = ${fmtSet(wantOf(o, r.zones))}` : `${o.say}: por ejemplo A = ${fmtSet(setsOf(o.sample).A)} y B = ${fmtSet(setsOf(o.sample).B)}`)).join(' · ')).join(' · ');
