    const halfW = () => Math.min(150, (W - 28) / 2), halfH = 92;

    function layout(w, h) { W = w; H = h; cy = 312; btn = { x: w / 2 - 62, y: h - 64, w: 124, h: 32 }; els.forEach(e => { const q = home(e); e.x = q.x; e.y = q.y; }); }
