        p.fill(shade(C.card, 0.85)); p.quad(-w * 0.32, h / 2 + 4, w * 0.32, h / 2 + 4, w * 0.2, -h / 2, -w * 0.2, -h / 2);
        p.stroke(body); p.strokeWeight(1.5); p.fill(C.card); p.quad(-w * 0.32, h / 2, w * 0.32, h / 2, w * 0.2, -h / 2 - 4, -w * 0.2, -h / 2 - 4);
