        p.noStroke(); p.fill(C.mute); p.textStyle(p.BOLD); p.textSize(10); p.textAlign(p.LEFT, p.CENTER); p.text('GUARDIÁN', 14, 44);
        for (let i = 0; i < TOTAL; i++) { p.fill(i < life ? C.coral : C.line); p.rect(80 + i * seg, 39, seg - 2, 10, 3); }
