        knobs.forEach(k => drawPracticeTrack(p, C, k.rail, ab[cur][k.i], (k.i ? 'b · ' : 'a · ') + nm[k.i], n(ab[cur][k.i]), k.i ? C.I : C.Z, drag === k));
