        p.fill(ok ? C.ok : C.mute); fitText(p, readouts(r, w, vec) || `${r.name || 'w'} = ${vt(w)}`, W / 2, 78, W - 24, 14);
        drawPlane(p, C, view);
        const ctx = p.drawingContext; ctx.save(); ctx.beginPath(); ctx.rect(view.box.x, view.box.y, view.box.w, view.box.h); ctx.clip();
