          p.noStroke(); p.fill(C.ink); p.textStyle(p.BOLD);
          const cy = y + g.s / 2 + (k === r.start || k === r.end ? g.s * 0.1 : 0), maxW = g.s - 12, fs = Math.min(17, g.s * 0.3);
          p.textSize(11);
