    solution: it => `$${it.val} \\cdot ${TK.FN[fn(it)]}\\,${it.deg}^\\circ \\approx ${res(it)}$ ${it.unit}`,
    prompt: it => it.q,
    foot: () => 'lado buscado = lado conocido × razón',
