      const h = Math.min(y0 - G.top - 78, 130), a = TK.rad(Math.max(28, Math.min(62, G.item.deg))), bw = Math.min(G.W - 130, h / Math.tan(a)), x0 = (G.W - bw) / 2, yb = y0 - 30;
