      const u = Math.min((G.W - 90) / xA, (ty - G.top - 96) / yB), x0 = (G.W - xA * u) / 2, yb = ty - 26, P = (x, y) => [x0 + x * u, yb - y * u];
      const O = P(0, 0), F = P(xA, 0), A = P(xA, yA), TR = P(xA, yB), B = P(xB, yB), TL = P(0, yB);
