      const V = [[x0, yb], [x0 + c * u, yb], [x0 + Cx * u, yb - Cy * u]], cen = [(V[0][0] + V[1][0] + V[2][0]) / 3, (V[0][1] + V[1][1] + V[2][1]) / 3];
      const out = (pt, d) => { const n = Math.hypot(pt[0] - cen[0], pt[1] - cen[1]) || 1; return [pt[0] + (pt[0] - cen[0]) / n * d, pt[1] + (pt[1] - cen[1]) / n * d]; };
