    demo: G => ({ from: G.knob, to: point(G.f.x + G.uv * Math.min(3, G.r.max[0]), G.f.y - G.uv * Math.min(3, G.r.max[1])) }),
    solve: G => [G.knob, point(G.f.x + G.uv * G.r.goal[0], G.f.y - G.uv * G.r.goal[1])],
